/**
 * export-week-pdf Edge Function
 *
 * GET ?week_start=YYYY-MM-DD — branded PDF for the caller's week data.
 * Uses caller JWT only (no service_role). RLS applies.
 */

import "jsr:@supabase/functions-js/edge-runtime.d.ts";
import { createClient } from "npm:@supabase/supabase-js@2";
import { PDFDocument, rgb } from "npm:pdf-lib@1.17.1";
import fontkit from "npm:@pdf-lib/fontkit@1.1.1";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
};

const WEEK_START_PATTERN = /^\d{4}-\d{2}-\d{2}$/;

const ORANGE = rgb(0xf7 / 255, 0xa2 / 255, 0x35 / 255);
const ORANGE_DARK = rgb(0xf0 / 255, 0x6a / 255, 0x3a / 255);
const DARK = rgb(0x1a / 255, 0x16 / 255, 0x13 / 255);
const MUTED = rgb(0x8a / 255, 0x81 / 255, 0x78 / 255);
const RULE = rgb(0xf2 / 255, 0xf2 / 255, 0xf2 / 255);
const CARD_FILL = rgb(0xf5 / 255, 0xf2 / 255, 0xed / 255);
const CARD_BORDER = rgb(0xe8 / 255, 0xe4 / 255, 0xde / 255);
const PILL_BG = rgb(0xfd / 255, 0xf1 / 255, 0xde / 255);
const WHITE = rgb(1, 1, 1);

const SECTION_GAP_BEFORE = 32;
const SECTION_GAP_AFTER = 16;
const SECTION_TITLE_SIZE = 12;
const RAIL_W = 3;
const RAIL_RADIUS = 1.5;
const RAIL_CONTENT_GAP = 14;
const RAIL_TOP_PAD = 3;
const RAIL_BOTTOM_PAD = 8;
const FOOTER_H = 16;
/** Content must stay above the footer band. */
const PAGE_CONTENT_BOTTOM = FOOTER_H + SECTION_GAP_AFTER;

const OSWALD_BOLD_BASE64 = "";

const OSWALD_REGULAR_BASE64 = "";

const WORDMARK_BASE64 = "";

const DAY_LABELS = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"];

const APPROACH_LABELS: Record<string, string> = {
  orange_base: "Orange Base",
  meal_bank: "KCPT Meal Bank",
  own: "My Own Meal",
};

type PdfFont = {
  widthOfTextAtSize: (text: string, size: number) => number;
};

function jsonResponse(body: Record<string, unknown>, status: number): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...corsHeaders, "Content-Type": "application/json" },
  });
}

function requiredEnv(name: string): string | null {
  const value = Deno.env.get(name);
  return value && value.length > 0 ? value : null;
}

function isValidWeekStart(value: unknown): value is string {
  return typeof value === "string" && WEEK_START_PATTERN.test(value);
}

function formatWeekRange(weekStart: string): string {
  const [year, month, day] = weekStart.split("-").map(Number);
  const monday = new Date(Date.UTC(year, month - 1, day));
  const sunday = new Date(Date.UTC(year, month - 1, day + 6));
  const months = [
    "Jan", "Feb", "Mar", "Apr", "May", "Jun",
    "Jul", "Aug", "Sep", "Oct", "Nov", "Dec",
  ];
  const fmt = (d: Date) =>
    months[d.getUTCMonth()] + " " + d.getUTCDate() + ", " + d.getUTCFullYear();
  // Same year → "Jul 20 - Jul 26, 2026"
  if (monday.getUTCFullYear() === sunday.getUTCFullYear()) {
    return (
      months[monday.getUTCMonth()] +
      " " +
      monday.getUTCDate() +
      " - " +
      months[sunday.getUTCMonth()] +
      " " +
      sunday.getUTCDate() +
      ", " +
      sunday.getUTCFullYear()
    );
  }
  return fmt(monday) + " - " + fmt(sunday);
}

function coerceNonNegotiables(raw: unknown): string[] {
  const names = ["", "", ""];
  if (!Array.isArray(raw)) return names;
  for (let i = 0; i < 3; i++) {
    const item = raw[i];
    if (typeof item === "string") names[i] = item;
    else if (
      item !== null &&
      typeof item === "object" &&
      !Array.isArray(item) &&
      typeof (item as Record<string, unknown>).name === "string"
    ) {
      names[i] = (item as Record<string, unknown>).name as string;
    }
  }
  return names;
}

function coerceString3(raw: unknown): string[] {
  const out = ["", "", ""];
  if (!Array.isArray(raw)) return out;
  for (let i = 0; i < 3; i++) {
    if (typeof raw[i] === "string") out[i] = raw[i] as string;
  }
  return out;
}

function base64ToBytes(b64: string): Uint8Array {
  const bin = atob(b64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return bytes;
}

function avgNumbers(values: unknown): number | null {
  if (!Array.isArray(values)) return null;
  const nums = values.filter((v): v is number => typeof v === "number");
  if (nums.length === 0) return null;
  return nums.reduce((a, b) => a + b, 0) / nums.length;
}

function formatCell(v: unknown): string {
  if (v === null || v === undefined) return "-";
  if (v === true) return "Y";
  if (typeof v === "boolean") return v ? "Y" : "-";
  if (typeof v === "number") {
    return Number.isInteger(v) ? String(v) : v.toFixed(1);
  }
  return String(v);
}

function fitCellSize(
  text: string,
  maxWidth: number,
  font: PdfFont,
  baseSize: number,
  minSize = 6,
): number {
  let size = baseSize;
  const pad = 2;
  while (size > minSize && font.widthOfTextAtSize(text, size) > maxWidth - pad) {
    size -= 0.5;
  }
  return size;
}

function trackedWidth(
  text: string,
  size: number,
  font: PdfFont,
  tracking: number,
): number {
  let w = 0;
  for (let i = 0; i < text.length; i++) {
    w += font.widthOfTextAtSize(text[i], size);
    if (i < text.length - 1) w += tracking;
  }
  return w;
}

function stringList(raw: unknown): string[] {
  if (!Array.isArray(raw)) return [];
  return raw
    .filter((x): x is string => typeof x === "string" && x.trim().length > 0)
    .map((x) => x.trim());
}

Deno.serve(async (req: Request) => {
  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: corsHeaders });
  }

  if (req.method !== "GET") {
    return jsonResponse({ error: "Method not allowed" }, 405);
  }

  const authHeader = req.headers.get("Authorization");
  if (!authHeader?.startsWith("Bearer ")) {
    return jsonResponse({ error: "Unauthorized" }, 401);
  }

  const token = authHeader.slice("Bearer ".length);
  const supabaseUrl = requiredEnv("SUPABASE_URL");
  const supabaseAnonKey = requiredEnv("SUPABASE_ANON_KEY");
  if (!supabaseUrl || !supabaseAnonKey) {
    console.error("export-week-pdf: missing environment configuration");
    return jsonResponse({ error: "Unable to export PDF" }, 500);
  }

  const callerClient = createClient(supabaseUrl, supabaseAnonKey, {
    global: { headers: { Authorization: authHeader } },
    auth: { autoRefreshToken: false, persistSession: false },
  });

  const {
    data: { user },
    error: userError,
  } = await callerClient.auth.getUser(token);

  if (userError || !user) {
    return jsonResponse({ error: "Unauthorized" }, 401);
  }

  const url = new URL(req.url);
  const weekStart = url.searchParams.get("week_start");
  if (!isValidWeekStart(weekStart)) {
    return jsonResponse(
      { error: "week_start query param is required and must be YYYY-MM-DD" },
      400,
    );
  }

  const [planRes, trackerRes, measurementRes] = await Promise.all([
    callerClient
      .from("weekly_base_plans")
      .select("*")
      .eq("user_id", user.id)
      .eq("week_start", weekStart)
      .maybeSingle(),
    callerClient
      .from("weekly_tracker_entries")
      .select("*")
      .eq("user_id", user.id)
      .eq("week_start", weekStart)
      .maybeSingle(),
    callerClient
      .from("weight_measurements")
      .select("*")
      .eq("user_id", user.id)
      .eq("week_start", weekStart)
      .maybeSingle(),
  ]);

  if (planRes.error || trackerRes.error || measurementRes.error) {
    console.error("export-week-pdf: select failed", {
      plan: planRes.error,
      tracker: trackerRes.error,
      measurement: measurementRes.error,
    });
    return jsonResponse({ error: "Unable to load week data" }, 500);
  }

  const plan = planRes.data as Record<string, unknown> | null;
  const trackerRow = trackerRes.data as Record<string, unknown> | null;
  const measurement = measurementRes.data as Record<string, unknown> | null;

  const nonNegotiables = coerceNonNegotiables(trackerRow?.habits);
  const wins = coerceString3(trackerRow?.wins);
  const nextWeekFocus = coerceString3(trackerRow?.next_week_focus);
  const metrics = (trackerRow?.daily_metrics ?? null) as Record<
    string,
    unknown
  > | null;

  try {
    const pdfDoc = await PDFDocument.create();
    pdfDoc.registerFontkit(fontkit);

    const fontBold = await pdfDoc.embedFont(base64ToBytes(OSWALD_BOLD_BASE64));
    const font = await pdfDoc.embedFont(base64ToBytes(OSWALD_REGULAR_BASE64));

    let page = pdfDoc.addPage([612, 792]);
    const margin = 48;
    const pageWidth = 612;
    const pageHeight = 792;
    const maxWidth = pageWidth - margin * 2;
    const contentX = margin + RAIL_CONTENT_GAP;
    const contentW = maxWidth - RAIL_CONTENT_GAP;
    const labelColW = 78;
    const dayColW = 56;
    const avgColW = contentW - labelColW - dayColW * 7;

    const logoBytes = base64ToBytes(WORDMARK_BASE64);
    const logoImage = await pdfDoc.embedPng(logoBytes);
    const logoH = 22;
    const logoW = (logoImage.width / logoImage.height) * logoH;

    let y = pageHeight - margin;

    const drawTrackedText = (
      text: string,
      x: number,
      baseline: number,
      size: number,
      f: PdfFont,
      color: ReturnType<typeof rgb>,
      tracking: number,
    ) => {
      let cx = x;
      for (let i = 0; i < text.length; i++) {
        const ch = text[i];
        page.drawText(ch, { x: cx, y: baseline, size, font: f, color });
        cx += f.widthOfTextAtSize(ch, size) + tracking;
      }
    };

    const drawTrackedRight = (
      text: string,
      rightX: number,
      baseline: number,
      size: number,
      f: PdfFont,
      color: ReturnType<typeof rgb>,
      tracking: number,
    ) => {
      const w = trackedWidth(text, size, f, tracking);
      drawTrackedText(text, rightX - w, baseline, size, f, color, tracking);
    };

    // --- Header ---
    page.drawImage(logoImage, {
      x: margin,
      y: y - logoH,
      width: logoW,
      height: logoH,
    });

    const title = "WEEKLY SUMMARY";
    const titleSize = 24;
    const titleTrack = 1.2;
    drawTrackedRight(
      title,
      pageWidth - margin,
      y - 16,
      titleSize,
      fontBold,
      DARK,
      titleTrack,
    );

    const weekRange = formatWeekRange(weekStart);
    const weekSize = 9;
    const weekW = font.widthOfTextAtSize(weekRange, weekSize);
    page.drawText(weekRange, {
      x: pageWidth - margin - weekW,
      y: y - 26,
      size: weekSize,
      font,
      color: MUTED,
    });

    y -= Math.max(logoH, 34) + 12;
    page.drawLine({
      start: { x: margin, y },
      end: { x: pageWidth - margin, y },
      thickness: 0.75,
      color: DARK,
    });
    y -= 10;

    let openRail: { page: typeof page; x: number; top: number } | null = null;

    const drawAccentRail = (
      targetPage: typeof page,
      x: number,
      top: number,
      bottom: number,
    ) => {
      const h = top - bottom;
      if (h < 2) return;
      const rr = Math.min(RAIL_RADIUS, RAIL_W / 2, h / 2);
      const color = ORANGE;
      if (rr <= 0) {
        targetPage.drawRectangle({
          x,
          y: bottom,
          width: RAIL_W,
          height: h,
          color,
        });
        return;
      }
      targetPage.drawRectangle({
        x: x + rr,
        y: bottom + rr,
        width: RAIL_W - 2 * rr,
        height: h - 2 * rr,
        color,
      });
      targetPage.drawRectangle({
        x: x + rr,
        y: bottom + h - rr,
        width: RAIL_W - 2 * rr,
        height: rr,
        color,
      });
      targetPage.drawRectangle({
        x: x + rr,
        y: bottom,
        width: RAIL_W - 2 * rr,
        height: rr,
        color,
      });
      targetPage.drawRectangle({
        x,
        y: bottom + rr,
        width: rr,
        height: h - 2 * rr,
        color,
      });
      targetPage.drawRectangle({
        x: x + RAIL_W - rr,
        y: bottom + rr,
        width: rr,
        height: h - 2 * rr,
        color,
      });
      targetPage.drawCircle({
        x: x + rr,
        y: bottom + rr,
        size: rr,
        color,
      });
      targetPage.drawCircle({
        x: x + RAIL_W - rr,
        y: bottom + rr,
        size: rr,
        color,
      });
      targetPage.drawCircle({
        x: x + rr,
        y: bottom + h - rr,
        size: rr,
        color,
      });
      targetPage.drawCircle({
        x: x + RAIL_W - rr,
        y: bottom + h - rr,
        size: rr,
        color,
      });
    };

    const beginSectionRail = (x: number, top: number) => {
      openRail = { page, x, top };
    };

    const endSectionRail = (bottomY: number = y) => {
      if (!openRail) return;
      if (openRail.page === page) {
        drawAccentRail(
          openRail.page,
          openRail.x,
          openRail.top,
          bottomY - RAIL_BOTTOM_PAD,
        );
      }
      openRail = null;
    };

    const ensureSpace = (needed: number) => {
      if (y - needed < PAGE_CONTENT_BOTTOM) {
        if (openRail && openRail.page === page) {
          drawAccentRail(
            openRail.page,
            openRail.x,
            openRail.top,
            y - RAIL_BOTTOM_PAD,
          );
        }
        openRail = null;
        page = pdfDoc.addPage([612, 792]);
        y = pageHeight - margin;
      }
    };

    // pdf-lib drawSvgPath fills are unreliable — build rounded rect from
    // rectangles + corner circles + edge strips, then a thin border.
    const drawRoundedRect = (
      x: number,
      bottom: number,
      w: number,
      h: number,
      r: number,
      color: ReturnType<typeof rgb>,
    ) => {
      const rr = Math.min(r, w / 2, h / 2);
      if (rr <= 0) {
        page.drawRectangle({ x, y: bottom, width: w, height: h, color });
        return;
      }
      // Center body
      page.drawRectangle({
        x: x + rr,
        y: bottom + rr,
        width: w - 2 * rr,
        height: h - 2 * rr,
        color,
      });
      // Edge strips between corners
      page.drawRectangle({
        x: x + rr,
        y: bottom + h - rr,
        width: w - 2 * rr,
        height: rr,
        color,
      });
      page.drawRectangle({
        x: x + rr,
        y: bottom,
        width: w - 2 * rr,
        height: rr,
        color,
      });
      page.drawRectangle({
        x: x,
        y: bottom + rr,
        width: rr,
        height: h - 2 * rr,
        color,
      });
      page.drawRectangle({
        x: x + w - rr,
        y: bottom + rr,
        width: rr,
        height: h - 2 * rr,
        color,
      });
      // Corner circles
      page.drawCircle({ x: x + rr, y: bottom + rr, size: rr, color });
      page.drawCircle({ x: x + w - rr, y: bottom + rr, size: rr, color });
      page.drawCircle({ x: x + rr, y: bottom + h - rr, size: rr, color });
      page.drawCircle({ x: x + w - rr, y: bottom + h - rr, size: rr, color });
      // Thin border (outer edge)
      const bw = 0.5;
      const bc = CARD_BORDER;
      page.drawLine({
        start: { x: x + rr, y: bottom + h },
        end: { x: x + w - rr, y: bottom + h },
        thickness: bw,
        color: bc,
      });
      page.drawLine({
        start: { x: x + rr, y: bottom },
        end: { x: x + w - rr, y: bottom },
        thickness: bw,
        color: bc,
      });
      page.drawLine({
        start: { x: x, y: bottom + rr },
        end: { x: x, y: bottom + h - rr },
        thickness: bw,
        color: bc,
      });
      page.drawLine({
        start: { x: x + w, y: bottom + rr },
        end: { x: x + w, y: bottom + h - rr },
        thickness: bw,
        color: bc,
      });
    };

    const drawSectionTitle = (
      label: string,
      opts?: { badge?: string; x?: number; width?: number },
    ) => {
      const x0 = opts?.x ?? margin;
      const w0 = opts?.width ?? maxWidth;
      y -= SECTION_GAP_BEFORE;
      ensureSpace(40);
      beginSectionRail(x0, y + RAIL_TOP_PAD);
      const t = label.toUpperCase();
      drawTrackedText(
        t,
        x0 + RAIL_CONTENT_GAP,
        y,
        SECTION_TITLE_SIZE,
        fontBold,
        DARK,
        0.6,
      );
      if (opts?.badge) {
        const badge = opts.badge.toUpperCase();
        const badgeSize = 7.5;
        const padX = 12;
        const padY = 5.5;
        const badgeW = fontBold.widthOfTextAtSize(badge, badgeSize);
        const boxW = badgeW + padX * 2;
        const boxH = badgeSize + padY * 2;
        const boxX = x0 + w0 - boxW;
        // Shared calc: pill centered on section title optical mid
        const titleOpticalCenter = y + SECTION_TITLE_SIZE / 2;
        const boxY = titleOpticalCenter - boxH / 2;
        drawRoundedRect(boxX, boxY, boxW, boxH, boxH / 2, PILL_BG);
        page.drawText(badge, {
          x: boxX + padX,
          y: boxY + padY,
          size: badgeSize,
          font: fontBold,
          color: ORANGE_DARK,
        });
      }
      y -= SECTION_GAP_AFTER;
    };

    const wrapText = (
      text: string,
      width: number,
      f: PdfFont,
      size: number,
    ): string[] => {
      const words = text.split(" ");
      const lines: string[] = [];
      let line = "";
      for (const word of words) {
        const test = line ? line + " " + word : word;
        if (f.widthOfTextAtSize(test, size) > width && line) {
          lines.push(line);
          line = word;
        } else {
          line = test;
        }
      }
      if (line) lines.push(line);
      return lines.length ? lines : [""];
    };

    const drawTextLine = (
      text: string,
      opts?: {
        bold?: boolean;
        size?: number;
        color?: ReturnType<typeof rgb>;
        x?: number;
        width?: number;
      },
    ) => {
      const size = opts?.size ?? 10;
      const f = opts?.bold ? fontBold : font;
      const color = opts?.color ?? DARK;
      const x0 = opts?.x ?? contentX;
      const w0 = opts?.width ?? contentW;
      for (const line of wrapText(text, w0, f, size)) {
        ensureSpace(size + 6);
        page.drawText(line, { x: x0, y, size, font: f, color });
        y -= size + 4;
      }
    };

    const drawSubhead = (label: string, x0: number) => {
      drawTrackedText(label.toUpperCase(), x0, y, 8, fontBold, MUTED, 0.8);
    };

    // --- Food Plan (2x2) ---
    const approach = plan ? String(plan.nutrition_approach ?? "") : "";
    const approachBadge = plan
      ? APPROACH_LABELS[approach] ?? (approach || undefined)
      : undefined;
    drawSectionTitle("Food Plan", { badge: approachBadge });

    if (!plan) {
      drawTextLine("Not filled this week.", { color: MUTED });
    } else {
      const breakfasts = stringList(plan.breakfasts);
      const lunches = stringList(plan.lunches);
      const snacks = [
        ...stringList(plan.trigger_snacks),
        ...stringList(plan.desserts),
      ];
      const evening = Array.isArray(plan.evening_meals)
        ? (plan.evening_meals as Record<string, unknown>[])
        : [];
      const dinners = evening
        .map((e) => (typeof e.meal === "string" ? e.meal.trim() : ""))
        .filter((m) => m.length > 0);

      const colGap = 14;
      const colW = (contentW - colGap) / 2;
      const leftX = contentX;
      const rightX = contentX + colW + colGap;
      const joinItems = (items: string[]) =>
        items.length ? items.join("  ·  ") : "-";

      const drawFoodCell = (
        label: string,
        items: string[],
        x0: number,
        topY: number,
      ): number => {
        let cy = topY;
        drawTrackedText(label.toUpperCase(), x0, cy, 8, fontBold, MUTED, 0.8);
        cy -= 14;
        const body = joinItems(items);
        const color = items.length ? DARK : MUTED;
        for (const line of wrapText(body, colW, font, 9.5)) {
          page.drawText(line, {
            x: x0,
            y: cy,
            size: 9.5,
            font,
            color,
          });
          cy -= 13;
        }
        return cy;
      };

      ensureSpace(90);
      const row1Top = y;
      const leftBottom = drawFoodCell("Breakfasts", breakfasts, leftX, row1Top);
      const rightBottom = drawFoodCell("Lunches", lunches, rightX, row1Top);
      y = Math.min(leftBottom, rightBottom) - 10;
      ensureSpace(70);
      const row2Top = y;
      const left2 = drawFoodCell("Dinners", dinners, leftX, row2Top);
      const right2 = drawFoodCell("Snacks", snacks, rightX, row2Top);
      y = Math.min(left2, right2) - 4;

      if (
        breakfasts.length === 0 &&
        lunches.length === 0 &&
        dinners.length === 0 &&
        snacks.length === 0
      ) {
        y = row1Top;
        drawTextLine("No meals set this week.", { color: MUTED });
      }
    }
    endSectionRail();

    // --- Non-Negotiables ---
    drawSectionTitle("Non-Negotiables");
    {
      const labels = nonNegotiables.map((s) => s.trim());
      const cols = 3;
      const gap = 10;
      const cardW = (contentW - gap * (cols - 1)) / cols;
      const cardH = 36;
      const radius = 14;
      ensureSpace(cardH + 8);
      for (let i = 0; i < 3; i++) {
        const x = contentX + i * (cardW + gap);
        const bottom = y - cardH;
        drawRoundedRect(x, bottom, cardW, cardH, radius, CARD_FILL);
        const label = labels[i] || "-";
        const empty = !labels[i];
        const size = fitCellSize(label, cardW - 16, font, 9.5);
        const tw = font.widthOfTextAtSize(label, size);
        page.drawText(label, {
          x: x + (cardW - tw) / 2,
          y: bottom + (cardH - size) / 2 + 1,
          size,
          font,
          color: empty ? MUTED : DARK,
        });
      }
      y -= cardH;
    }
    endSectionRail();

    // --- Daily Numbers ---
    drawSectionTitle("Daily Numbers");

    const drawCheckmark = (cx: number, cy: number) => {
      // Symmetric stroke extents about cx / cy (matches number baselines)
      page.drawLine({
        start: { x: cx - 3, y: cy + 1 },
        end: { x: cx - 0.5, y: cy - 2.5 },
        thickness: 1.4,
        color: ORANGE_DARK,
      });
      page.drawLine({
        start: { x: cx - 0.5, y: cy - 2.5 },
        end: { x: cx + 3, y: cy + 2.5 },
        thickness: 1.4,
        color: ORANGE_DARK,
      });
    };

    const drawCenterCell = (
      text: string,
      centerX: number,
      colWidth: number,
      baseSize: number,
      useBold: boolean,
      color: ReturnType<typeof rgb>,
    ) => {
      const f = useBold ? fontBold : font;
      const size = fitCellSize(text, colWidth, f, baseSize);
      const tw = f.widthOfTextAtSize(text, size);
      page.drawText(text, {
        x: centerX - tw / 2,
        y,
        size,
        font: f,
        color,
      });
    };

    if (!trackerRow || !metrics) {
      drawTextLine("No daily numbers recorded this week.", { color: MUTED });
    } else {
      const rowH = 22;
      const pillarKeys = [
        { key: "calories", label: "Calories" },
        { key: "protein", label: "Protein (g)" },
        { key: "water", label: "Water (L)" },
        { key: "steps", label: "Steps" },
        { key: "workout", label: "Workout" },
      ] as const;

      ensureSpace(rowH * (pillarKeys.length + 1) + 12);
      // Shared column-center grid (SoT for headers, values, workout icons)
      const dayCenter = (i: number) =>
        contentX + labelColW + dayColW * i + dayColW / 2;
      const avgCenter =
        contentX + labelColW + dayColW * 7 + avgColW / 2;

      // Header
      page.drawText("METRIC", {
        x: contentX,
        y,
        size: 8,
        font: fontBold,
        color: DARK,
      });
      for (let i = 0; i < 7; i++) {
        drawCenterCell(DAY_LABELS[i], dayCenter(i), dayColW, 8, false, MUTED);
      }
      drawCenterCell("Avg", avgCenter, avgColW, 8, true, ORANGE_DARK);
      y -= rowH;

      for (let pi = 0; pi < pillarKeys.length; pi++) {
        const p = pillarKeys[pi];
        ensureSpace(rowH + 6);
        page.drawText(p.label, {
          x: contentX,
          y,
          size: 9,
          font: fontBold,
          color: DARK,
        });

        const series = metrics[p.key];
        for (let i = 0; i < 7; i++) {
          const raw = Array.isArray(series) ? series[i] : null;
          if (p.key === "workout") {
            if (raw === true) {
              drawCheckmark(dayCenter(i), y);
            } else {
              drawCenterCell("-", dayCenter(i), dayColW, 9, false, MUTED);
            }
          } else {
            const text = formatCell(raw);
            const empty = text === "-";
            drawCenterCell(
              text,
              dayCenter(i),
              dayColW,
              9,
              false,
              empty ? MUTED : DARK,
            );
          }
        }

        let avgText = "-";
        let avgMuted = true;
        if (p.key === "workout") {
          const count = Array.isArray(series)
            ? series.filter((v) => v === true).length
            : 0;
          avgText = count + "/7";
          avgMuted = false;
        } else {
          const avg = avgNumbers(series);
          if (avg != null) {
            avgMuted = false;
            avgText =
              p.key === "water" ? avg.toFixed(1) : String(Math.round(avg));
          }
        }
        drawCenterCell(
          avgText,
          avgCenter,
          avgColW,
          9,
          true,
          avgMuted ? MUTED : ORANGE_DARK,
        );

        y -= 5;
        if (pi < pillarKeys.length - 1) {
          page.drawLine({
            start: { x: contentX, y },
            end: { x: contentX + contentW, y },
            thickness: 0.5,
            color: RULE,
          });
        }
        y -= rowH - 5;
      }
    }
    endSectionRail();

    // --- Sunday Reset (left) + Measurements (right) ---
    const twoColGap = 22;
    const colWidth = (maxWidth - twoColGap) / 2;
    const rightColX = margin + colWidth + twoColGap;
    const leftContentX = margin + RAIL_CONTENT_GAP;
    const rightContentX = rightColX + RAIL_CONTENT_GAP;
    const colContentW = colWidth - RAIL_CONTENT_GAP;

    const winList = wins.map((s) => s.trim()).filter(Boolean);
    const focusList = nextWeekFocus.map((s) => s.trim()).filter(Boolean);

    type BulletLine =
      | { kind: "sub"; text: string }
      | { kind: "muted"; text: string }
      | { kind: "item"; text: string; bullet: boolean };
    const leftLines: BulletLine[] = [];
    const pushItems = (items: string[]) => {
      if (items.length === 0) {
        leftLines.push({ kind: "muted", text: "-" });
        return;
      }
      for (const w of items) {
        const lines = wrapText(w, colContentW - 12, font, 9.5);
        lines.forEach((ln, idx) => {
          leftLines.push({ kind: "item", text: ln, bullet: idx === 0 });
        });
      }
    };
    if (!trackerRow || (winList.length === 0 && focusList.length === 0)) {
      leftLines.push({ kind: "muted", text: "Not completed this week" });
    } else {
      leftLines.push({ kind: "sub", text: "WINS" });
      pushItems(winList);
      leftLines.push({ kind: "sub", text: "NEXT WEEK FOCUS" });
      pushItems(focusList);
    }

    const measureFields: { key: string; label: string; unit: string }[] = [
      { key: "weight", label: "Weight", unit: "lb" },
      { key: "waist", label: "Waist", unit: "in" },
      { key: "hips", label: "Hips", unit: "in" },
      { key: "arm", label: "Arm", unit: "in" },
      { key: "thigh", label: "Thigh", unit: "in" },
      { key: "calve", label: "Calve", unit: "in" },
    ];
    const measureRows = measureFields.map((f) => {
      const v = measurement?.[f.key];
      const has = typeof v === "number";
      return {
        label: f.label,
        value: has ? v + " " + f.unit : "-",
        muted: !has,
      };
    });

    y -= SECTION_GAP_BEFORE;
    const leftBodyH = leftLines.reduce((h, l) => {
      if (l.kind === "sub") return h + 18;
      return h + 16;
    }, 0);
    const rightBodyH = measureRows.length * 20;
    ensureSpace(SECTION_GAP_AFTER + Math.max(leftBodyH, rightBodyH) + 12);
    const sectionTop = y;

    // Left header
    drawTrackedText(
      "SUNDAY RESET",
      leftContentX,
      sectionTop,
      SECTION_TITLE_SIZE,
      fontBold,
      DARK,
      0.6,
    );

    const contentTop = sectionTop - SECTION_GAP_AFTER;
    let leftY = contentTop;
    for (const l of leftLines) {
      if (l.kind === "sub") {
        drawTrackedText(l.text, leftContentX, leftY, 8, fontBold, MUTED, 0.8);
        leftY -= 18;
      } else if (l.kind === "muted") {
        page.drawText(l.text, {
          x: leftContentX,
          y: leftY,
          size: 9.5,
          font,
          color: MUTED,
        });
        leftY -= 16;
      } else {
        if (l.bullet) {
          page.drawCircle({
            x: leftContentX + 3,
            y: leftY + 3,
            size: 1.6,
            color: DARK,
          });
        }
        page.drawText(l.text, {
          x: leftContentX + 12,
          y: leftY,
          size: 9.5,
          font,
          color: DARK,
        });
        leftY -= 16;
      }
    }

    // Right header
    drawTrackedText(
      "MEASUREMENTS",
      rightContentX,
      sectionTop,
      SECTION_TITLE_SIZE,
      fontBold,
      DARK,
      0.6,
    );

    let rightY = contentTop;
    for (let i = 0; i < measureRows.length; i++) {
      const row = measureRows[i];
      page.drawText(row.label, {
        x: rightContentX,
        y: rightY,
        size: 9,
        font,
        color: MUTED,
      });
      const size = 10;
      const f = fontBold;
      const tw = f.widthOfTextAtSize(row.value, size);
      page.drawText(row.value, {
        x: rightContentX + colContentW - tw,
        y: rightY,
        size,
        font: f,
        color: row.muted ? MUTED : DARK,
      });
      rightY -= 4;
      if (i < measureRows.length - 1) {
        page.drawLine({
          start: { x: rightContentX, y: rightY },
          end: { x: rightContentX + colContentW, y: rightY },
          thickness: 0.5,
          color: RULE,
        });
      }
      rightY -= 16;
    }

    drawAccentRail(
      page,
      margin,
      sectionTop + RAIL_TOP_PAD,
      leftY - RAIL_BOTTOM_PAD,
    );
    drawAccentRail(
      page,
      rightColX,
      sectionTop + RAIL_TOP_PAD,
      rightY - RAIL_BOTTOM_PAD,
    );

    y = Math.min(leftY, rightY);

    // --- Footer with banded gradient (flush to page bottom) ---
    const footerBottom = 0;
    const footerText = "CONSISTENCY BEATS PERFECTION";
    const bands = 16;
    const bandW = pageWidth / bands;
    const oR = 0xf7 / 255;
    const oG = 0xa2 / 255;
    const oB = 0x35 / 255;
    // Narrower orange→red range (less extreme dark end)
    const dR = 0xf0 / 255;
    const dG = 0x6a / 255;
    const dB = 0x3a / 255;
    for (let i = 0; i < bands; i++) {
      const t = i / (bands - 1);
      page.drawRectangle({
        x: i * bandW,
        y: footerBottom,
        width: bandW + 0.5,
        height: FOOTER_H,
        color: rgb(oR + (dR - oR) * t, oG + (dG - oG) * t, oB + (dB - oB) * t),
      });
    }
    // Soft top corners: cover square corners with white so bar reads rounded
    const cr = 8;
    page.drawSvgPath(
      "M 0 " + (footerBottom + FOOTER_H) +
        " L 0 " + (footerBottom + FOOTER_H - cr) +
        " Q 0 " + (footerBottom + FOOTER_H) + " " + cr + " " + (footerBottom + FOOTER_H) +
        " Z",
      { color: WHITE, borderWidth: 0 },
    );
    page.drawSvgPath(
      "M " + pageWidth + " " + (footerBottom + FOOTER_H) +
        " L " + pageWidth + " " + (footerBottom + FOOTER_H - cr) +
        " Q " + pageWidth + " " + (footerBottom + FOOTER_H) + " " + (pageWidth - cr) + " " + (footerBottom + FOOTER_H) +
        " Z",
      { color: WHITE, borderWidth: 0 },
    );
    const footSize = 9;
    const footTrack = 1.4;
    const footW = trackedWidth(footerText, footSize, fontBold, footTrack);
    drawTrackedText(
      footerText,
      (pageWidth - footW) / 2,
      footerBottom + (FOOTER_H - footSize) / 2,
      footSize,
      fontBold,
      WHITE,
      footTrack,
    );

    const pdfBytes = await pdfDoc.save();
    return new Response(pdfBytes, {
      status: 200,
      headers: {
        ...corsHeaders,
        "Content-Type": "application/pdf",
        "Content-Disposition":
          'attachment; filename="kcpt-week-' + weekStart + '.pdf"',
      },
    });
  } catch (err) {
    console.error("export-week-pdf: generate failed", err);
    return jsonResponse({ error: "Unable to generate PDF" }, 500);
  }
});
